// === Tab: verse ===
//Verse
//by Nur Didem Murtezaoglu

//based on Coding Challenge #24 : Perlin Noise Flow Field by The Coding Train (Daniel Shiffman)
//link: https://www.youtube.com/watch?v=BjoM9oKOAKY
//Perlin Noise by yasai
//link: https://www.openprocessing.org/sketch/494102


var particles_a = [];
var particles_b = [];
var particles_c = [];
var frequency =300;  //frequency, number of particle objects
var noisePattern = 900;  //noise value for perlin flow equation
var particleRadius = 1;  //thickness of the particles (lines)


function setup(){
    var universe = createCanvas(1450, 800);
	background(0);

    //initiate particle sets for each array
	for(var i = 0; i < frequency; i++){
		particles_a[i] = new Particle();
		particles_b[i] = new Particle();
		particles_c[i] = new Particle();
	}
}

function draw() {
	noStroke();
		for(var i = 0; i < frequency; i++){
		var a = map(i,0,frequency,0,250);

        //particle array A
		fill(particles_a[i].c, a);
		particles_a[i].move();
        particles_a[i].show(particleRadius);
		particles_a[i].edges();
        particles_a[i].checkColor(167, 138, 112, 206, 252, 253); //light-colors

        //particle array B
		fill(particles_b[i].c, a);
		particles_b[i].move();
		particles_b[i].show(particleRadius);
		particles_b[i].edges();
        particles_b[i].checkColor(146, 70, 32, 37, 55, 139); //midi-colors

        //particle array C
		fill(particles_c[i].c, a);
		particles_c[i].move();
		particles_c[i].show(particleRadius);
		particles_c[i].edges();
		particles_c[i].checkColor(119, 75, 59, 77, 113, 210); //dark-colors

	}  
}




// === Tab: particle ===
class Particle{
  constructor() {
    this.position = createVector(random(width), random(height));
	this.velocity = createVector(0, 0);
	this.acc = 0.2;
    this.c = color(200, 0, 0, 30);
  }

  move(){
    var angle = noise(this.position.x/noisePattern, this.position.y/noisePattern)*TWO_PI*noisePattern;
	this.velocity = p5.Vector.fromAngle(angle);
    //NOTE: switch
	this.velocity.mult(this.acc);
    this.position.add(this.velocity);
  }


  //edges() : keep the particle in the canvas 
  edges(){
    //assign random position if particle leaves the canvas
	if(this.position.x > width || this.position.x < 0 || this.position.y > height || this.position.y < 0){
      //avoid assigning position at the edge of the canvas
	  this.position.x = random(50, width);
	  this.position.y = random(50, height);
	}
  }

  //show(radius) : draw a particle as an ellipse with radius 'r'
  show(r){
		ellipse(this.position.x, this.position.y, r, r);
	}

  //checkColor() : change RGB color values according to x-pos of the particle
  checkColor (r1, g1, b1, r2, g2, b2) {
    this.r = map(this.position.x, 0, width, r1, r2);
    this.g = map(this.position.x, 0, width, g1, g2);
    this.b = map(this.position.x, 0, width, b1, b2);
    this.c = color(this.r, this.g, this.b, 30);
  }
}

